package dev.eugheist.tc4modern;
import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.world.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.Level;
public final class DeconstructorEntity extends BlockEntity implements net.minecraft.world.WorldlyContainer {
 public final SimpleContainer inventory=new SimpleContainer(1);public final thaumcraft.common.tiles.DeconstructionState state=new thaumcraft.common.tiles.DeconstructionState();
 public DeconstructorEntity(BlockPos pos,BlockState block){super(BasicsContent.DECONSTRUCTOR_ENTITY.get(),pos,block);inventory.addListener(c->changed());}
 public void changed(){setChanged();if(level!=null&&!level.isClientSide)level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),3);}
 static thaumcraft.api.aspects.AspectList tags(net.minecraft.world.item.ItemStack stack,Level level){var result=new thaumcraft.api.aspects.AspectList();RecipeAspects.get(stack,level).forEach((tag,n)->{var a=thaumcraft.api.aspects.Aspect.getAspect(tag);if(a!=null)result.add(a,n);});return result;}
 public static void tick(Level level,BlockPos pos,BlockState block,DeconstructorEntity table){if(level.isClientSide)return;if(table.state.tick(tags(table.getItem(0),level),level.random::nextInt,()->table.removeItem(0,1)))table.changed();}
 /** The original GUI click: one point of the split-off aspect into the player's pool, popup and scanner sync. */
 void give(net.minecraft.server.level.ServerPlayer player){var gained=state.aspect;if(gained==null)return;var knowledge=ResearchKnowledge.load(player.getPersistentData());knowledge.addAspectPool("current",gained,(short)1);ResearchKnowledge.save(player.getPersistentData(),knowledge);state.aspect=null;changed();ThaumometerItem.sync(player,"");AspectGain.send(player,gained,1);}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);ContainerHelper.saveAllItems(tag,inventory.getItems(),lookup);if(state.aspect!=null)tag.putString("Aspect",state.aspect.getTag());}
 @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);inventory.getItems().clear();ContainerHelper.loadAllItems(tag,inventory.getItems(),lookup);state.aspect=thaumcraft.api.aspects.Aspect.getAspect(tag.getString("Aspect"));state.breaktime=0;}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){return saveWithoutMetadata(lookup);}
 @Override public net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket getUpdatePacket(){return net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket.create(this);}
 @Override public int getContainerSize(){return 1;}@Override public boolean isEmpty(){return inventory.isEmpty();}@Override public net.minecraft.world.item.ItemStack getItem(int slot){return inventory.getItem(slot);}@Override public net.minecraft.world.item.ItemStack removeItem(int slot,int n){return inventory.removeItem(slot,n);}@Override public net.minecraft.world.item.ItemStack removeItemNoUpdate(int slot){return inventory.removeItemNoUpdate(slot);}@Override public void setItem(int slot,net.minecraft.world.item.ItemStack stack){inventory.setItem(slot,stack);}@Override public void clearContent(){inventory.clearContent();}@Override public boolean stillValid(net.minecraft.world.entity.player.Player p){return level!=null&&level.getBlockEntity(worldPosition)==this&&p.distanceToSqr(worldPosition.getCenter())<=64;}
 @Override public int[] getSlotsForFace(Direction side){return side==Direction.UP?new int[0]:new int[]{0};}@Override public boolean canPlaceItem(int i,net.minecraft.world.item.ItemStack s){return level!=null&&tags(s,level).size()>0;}@Override public boolean canPlaceItemThroughFace(int i,net.minecraft.world.item.ItemStack s,Direction d){return d!=Direction.UP&&canPlaceItem(i,s);}@Override public boolean canTakeItemThroughFace(int i,net.minecraft.world.item.ItemStack s,Direction d){return true;}
}
